mod engine {
    include!("../../quintic_resultant_20261016_v1/src/main.rs");
    fn eval(f: &F, h: &P, x: &N) -> N {h.iter().rev().fold(n(0),|r,a|f.add(&f.mul(&r,x),a))}
    fn betas(f:&F,basis:&[N])->Vec<N>{let mut v=basis.to_vec();let mut b=vec![];for i in 0..v.len(){let t=v[i].clone();assert!(!t.is_zero());for x in v.iter_mut().skip(i+1){*x=f.add(&f.mul(x,x),&f.mul(&t,x));}b.push(t);}b}
    fn lev(f:&F,x:&N,beta:&[N])->N{beta.iter().fold(x.clone(),|r,b|f.add(&f.mul(&r,&r),&f.mul(b,&r)))}
    // Column i is X^(2i) mod H; arbitrary monic degrees1..5.
    fn cols(f:&F,h:&P)->Vec<P>{let m=h.len()-1;assert!(m>0&&m<=5&&h[m]==n(1));(0..m).map(|i|{let mut p=vec![n(0);2*i+1];p[2*i]=n(1);f.rem(p,h,false)}).collect()}
    fn square(f:&F,r:&P,c:&[P])->P{let m=c.len();let mut z=vec![n(0);m];for(i,a)in r.iter().enumerate(){let a=f.mul(a,a);for(j,b)in c[i].iter().enumerate(){z[j]=f.add(&z[j],&f.mul(&a,b));}}trim(z)}
    fn rem_l(f:&F,h:&P,beta:&[N],offset:&N)->(P,Vec<P>){let c=cols(f,h);let mut r=f.rem(vec![n(0),n(1)],h,false);for b in beta{let mut s=square(f,&r,&c);s.resize(h.len()-1,n(0));for(i,a)in r.iter().enumerate(){s[i]=f.add(&s[i],&f.mul(b,a));}r=trim(s);}if r.is_empty(){r.push(n(0));}r[0]=f.add(&r[0],&lev(f,offset,beta));(trim(r),c)}
    fn support(f:&F,h:&P,beta:&[N],offset:&N)->bool{let(mut r,c)=rem_l(f,h,beta,offset);let mut power=1;while power<h.len()-1{r=square(f,&r,&c);power*=2;}r.is_empty()}
    fn reference(f:&F,h:&P,beta:&[N],offset:&N)->bool {if f.sf(h,2){rem_l(f,h,beta,offset).0.is_empty()}else{support(f,h,beta,offset)}}
    // U !=0. Tests V/U in the squared affine domain without division or square root.
    fn rational_member(f:&F,u:&N,v:&N,beta:&[N],offset:&N)->bool{assert!(!u.is_zero());let mut p=v.clone();let mut w=u.clone();for b in beta{let b2=f.mul(b,b);p=f.add(&f.mul(&p,&p),&f.mul(&f.mul(&b2,&w),&p));w=f.mul(&w,&w);}let target=lev(f,offset,beta);f.add(&p,&f.mul(&f.mul(&target,&target),&w)).is_zero()}
    fn dispatch(f:&F,h:&P,beta:&[N],offset:&N)->(bool,&'static str){assert_eq!(h.len(),6);let u=f.add(&h[2],&f.mul(&h[4],&h[3]));let v=f.add(&h[0],&f.mul(&h[4],&h[1]));let delta=f.add(&f.add(&f.mul(&v,&v),&f.mul(&h[3],&f.mul(&u,&v))),&f.mul(&h[1],&f.mul(&u,&u)));
      if !delta.is_zero(){return(rem_l(f,h,beta,offset).0.is_empty(),"squarefree");}
      if u.is_zero(){assert!(v.is_zero());if lev(f,&h[4],beta)!=lev(f,offset,beta){return(false,"exceptional_linear_outside");}let bs=beta.iter().map(|b|f.mul(b,b)).collect::<Vec<_>>();return(support(f,&vec![h[1].clone(),h[3].clone(),n(1)],&bs,&f.mul(offset,offset)),"exceptional_quadratic");}
      if v.is_zero(){if !lev(f,offset,beta).is_zero(){return(false,"repeated_zero_outside");}assert!(h[0].is_zero()&&h[1].is_zero());return(support(f,&h[2..].to_vec(),beta,offset),"repeated_zero_cubic");}
      if !rational_member(f,&u,&v,beta,offset){return(false,"repeated_outside_reject");}
      let t=f.mul(&v,&f.inv(&u));let mut q=h.clone();let mut quotient=vec![n(0);4];while q.len()>=3{let j=q.len()-3;let a=q.last().unwrap().clone();quotient[j]=a.clone();q[j]=f.add(&q[j],&f.mul(&a,&t));q[j+2]=n(0);q=trim(q);}assert!(q.is_empty());(support(f,&trim(quotient),beta,offset),"repeated_cubic")
    }
    fn tiny_support_oracle(f:&F,h:&P,domain:&[N])->bool{let mut total=0;for i in 0..f.order().to_usize().unwrap(){let x=N::from(i);if eval(f,h,&x).is_zero(){if !domain.contains(&x){return false;}let m=(1..h.len()).find(|k|{let d=trim((*k..h.len()).map(|j|if j&k==*k{h[j].clone()}else{n(0)}).collect());!eval(f,&d,&x).is_zero()}).unwrap();total+=m;}}total==5}
    // p-linear rational membership for prime and odd quadratic extension fields.
    fn rational_odd(f:&F,u:&N,v:&N,beta:&[N],offset:&N)->bool{assert!(!u.is_zero());let p=match &f.k{Kind::Prime(p)=>p.clone(),Kind::Odd(p,_)=>n(*p),_=>panic!("odd field required")};let pm=&p-n(1);let mut z=v.clone();let mut w=u.clone();let mut target=offset.clone();for b in beta{let factor=f.pow(b,pm.clone());z=f.sub(&f.pow(&z,p.clone()),&f.mul(&f.mul(&factor,&f.pow(&w,pm.clone())),&z));w=f.pow(&w,p.clone());target=f.sub(&f.pow(&target,p.clone()),&f.mul(&factor,&target));}f.sub(&z,&f.mul(&target,&w)).is_zero()}
    fn odd_controls()->usize{let mut cases=0;for f in fields().into_iter().filter(|f|matches!(f.k,Kind::Prime(ref p)if p.bits()<8)||matches!(f.k,Kind::Odd(..))){let q=f.order().to_usize().unwrap();let p=f.characteristic()as usize;for dimension in 0..=1{let beta=if dimension==0{vec![]}else{vec![n(1)]};for offset in [n(0),N::from(p%q)]{let domain=if dimension==0{vec![offset.clone()]}else{(0..p).map(|i|f.add(&offset,&N::from(i))).collect::<Vec<_>>()};for ui in 1..q{for vi in 0..q{let u=N::from(ui);let v=N::from(vi);let expect=domain.iter().any(|x|f.mul(x,&u)==v);assert_eq!(rational_odd(&f,&u,&v,&beta,&offset),expect);cases+=1;}}}}}cases}
    pub fn controls()->Value{let mut count=0;let mut rational=0;let mut branches=std::collections::BTreeMap::new();for f in fields().into_iter().filter(|f|matches!(f.k,Kind::Binary(d,_)if d<=4)){let q=f.order().to_usize().unwrap();let basis=vec![n(1)];let beta=betas(&f,&basis);for offset in [n(0),n(2)]{let domain=vec![offset.clone(),f.add(&offset,&n(1))];let lim=if q==4{1024}else{256};for i in 0..lim{let mut v=(i*1664525usize+1013904223usize)%q.pow(5);let mut h=vec![];for _ in 0..5{h.push(N::from(v%q));v/=q;}h.push(n(1));let expect=tiny_support_oracle(&f,&h,&domain);assert_eq!(reference(&f,&h,&beta,&offset),expect);let(got,branch)=dispatch(&f,&h,&beta,&offset);assert_eq!(got,expect,"{} {:?}",f.name,h);*branches.entry(branch).or_insert(0usize)+=1;count+=1;}for u in 1..q{for v in 0..q{let u=N::from(u);let v=N::from(v);let t=f.mul(&v,&f.inv(&u));let expected=domain.iter().any(|x|f.mul(x,x)==t);assert_eq!(rational_member(&f,&u,&v,&beta,&offset),expected);rational+=1;}}}}json!({"status":"passed","support_oracle_cases":count,"odd_prime_extension_rational_cases":odd_controls(),"rational_membership_cases":rational,"branches":branches,"oracle":"Hasse multiplicity sum over the entire tiny field; no quotient division or rational recurrence"})}
    pub fn run(id:&str,seed:u64)->Value{let begin=Instant::now();let mut rows=vec![];let mut rng=seed;for f in fields().into_iter().filter(|f|matches!(f.k,Kind::Binary(d,_)if d>=83)){let q=f.order();let mut wide=||{let mut x=n(0);for _ in 0..q.bits().div_ceil(64){rng^=rng<<13;rng^=rng>>7;rng^=rng<<17;x=(x<<64)+N::from(rng);}x%&q};let offset=wide();let s=wide();let scale=if s.is_zero(){n(1)}else{s};let basis=(0..18).map(|i|f.mul(&scale,&(N::one()<<i))).collect::<Vec<_>>();let beta=betas(&f,&basis);let outside=f.add(&offset,&f.mul(&scale,&(N::one()<<18)));assert_ne!(lev(&f,&outside,&beta),lev(&f,&offset,&beta));
      let mut hs=vec![];for kind in 0..6{let mut roots=(0..5).map(|j|f.add(&offset,&f.mul(&scale,&N::from((j*173+31)as u32)))).collect::<Vec<_>>();match kind{1=>roots[1]=roots[0].clone(),2=>{roots[0]=outside.clone();roots[1]=outside.clone();},3=>{roots[1]=roots[0].clone();roots[2]=roots[0].clone();},4=>{roots[1]=roots[0].clone();roots[3]=roots[2].clone();},5=>roots=vec![outside.clone();5],_=>{}}let h=f.product(&roots);let expected=roots.iter().all(|x|lev(&f,x,&beta)==lev(&f,&offset,&beta));hs.push((h,expected));}
      let aa=(0..2).map(|_|{let t=Instant::now();for _ in 0..4{for(h,_)in &hs{std::hint::black_box(reference(&f,h,&beta,&offset));}}t.elapsed().as_secs_f64()}).collect::<Vec<_>>();let mut times=vec![vec![],vec![]];let mut answers=vec![vec![],vec![]];let mut branches=vec![];for rep in 0..5{for method in if rep%2==0{[0,1]}else{[1,0]}{let t=Instant::now();let mut a=vec![];for _ in 0..4{for(h,expected)in &hs{let got=if method==0{reference(&f,h,&beta,&offset)}else{dispatch(&f,h,&beta,&offset).0};assert_eq!(got,*expected);a.push(got);}}times[method].push(t.elapsed().as_secs_f64());answers[method]=a;}}for(h,_)in &hs{branches.push(dispatch(&f,h,&beta,&offset).1);}assert_eq!(answers[0],answers[1]);rows.push(json!({"field":f.name,"seconds_internal_diagnostic":times,"aa_internal_seconds":aa,"batch_iterations":4,"branches":branches,"answers":answers[0],"polynomials":hs.iter().map(|(h,_)|h.iter().map(|x|x.to_str_radix(16)).collect::<Vec<_>>()).collect::<Vec<_>>() }));assert!(begin.elapsed().as_secs()<65);}
      json!({"schema":"scientific_result_v1","experiment_id":id,"status":"passed","summary":"Conditional repeated-root support agrees with exact binary-domain reference across six fields.","evidence":{"rows":rows,"seed":seed,"fields":6,"cases":36,"scope":"all-support predicate only, not original all-roots search","original_root_count_exact":null,"release_gate_claim":false,"external_fastest_comparison":"not_run","novelty_claim":false},"next_actions":["Reject blanket dispatch if charged complete predicate regresses; follow the per-branch evidence.","Derive a whole-parameter-cell condition from the denominator-cleared recurrence; retain exceptional and squarefree branches.","Develop the distinct prime-field domain adapter and matched complete F4/F5/F6 comparisons."]})
    }
}
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|s|s=="controls"){println!("{}",engine::controls());return;}let t=std::time::Instant::now();let mut r=engine::run(a.get(1).expect("id"),a.get(2).expect("seed").parse().unwrap());let mut encoded=r.to_string();if t.elapsed().as_secs()>=70{r["status"]=serde_json::json!("inconclusive");r["summary"]=serde_json::json!("late complete serialization; no completion accepted");encoded=r.to_string();}println!("{encoded}");}
